import{_ as e,o as a,c as s,a2 as r}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"What Zenin is","description":"Product purpose, supported asset classes, provider-dependent data coverage, and the financial-information disclaimer.","frontmatter":{"title":"What Zenin is","description":"Product purpose, supported asset classes, provider-dependent data coverage, and the financial-information disclaimer.","audience":"user","status":"current","last_verified":"2026-07-19T00:00:00.000Z"},"headers":[],"relativePath":"get-started/what-is-zenin.md","filePath":"get-started/what-is-zenin.md","lastUpdated":null}'),o={name:"get-started/what-is-zenin.md"};function n(i,t,d,c,l,p){return a(),s("div",null,[...t[0]||(t[0]=[r('<h1 id="what-zenin-is" tabindex="-1">What Zenin is</h1><p>Zenin is a <strong>multi-asset investment intelligence workspace for individual investors</strong>. It brings portfolio context, market data, research, macro events, and decision workflows into one place so you can understand what may affect your investments — not just track prices.</p><p>Zenin&#39;s purpose is to help you connect market context to your portfolio, make a decision with that context, and keep the rationale for later review.</p><blockquote><h2 id="disclaimer" tabindex="-1">Disclaimer</h2><p>Zenin provides <strong>research and decision-support tools only</strong>. It is <strong>not</strong> investment, tax, legal, or financial advice. Strategy probabilities, tax estimates, and prediction-market signals are informational outputs and should be independently reviewed before any investment decision.</p></blockquote><h2 id="what-you-can-do" tabindex="-1">What you can do</h2><ul><li><strong>Home</strong> — portfolio snapshot, performance, positions, movers, market context, saved views, alerts, and next-step handoffs.</li><li><strong>Watchlist</strong> — search, add, import, and monitor multi-asset watchlists; inspect earnings and macro context.</li><li><strong>Research</strong> — open contextual asset research from a Watchlist, Portfolio, Home, or Intelligence surface, with portfolio-aware actions.</li><li><strong>Portfolio</strong> — track holdings, valuation, performance, exposure, rebalance planning, trade records, exports, and alerts.</li><li><strong>Intelligence and Analytics</strong> — market signals, event calendars, macro regime context, research queues, and provider health.</li><li><strong>Options and predictions</strong> — options chains, calculators, strategy workflows, whale activity, and prediction-market snapshots.</li><li><strong>Journal and tax</strong> — capture trade decisions and reviews, inspect outcomes, and estimate tax scenarios from recorded activity.</li></ul><h2 id="supported-assets" tabindex="-1">Supported assets</h2><table tabindex="0"><thead><tr><th>Asset class</th><th>Examples</th><th>Primary Zenin surface</th></tr></thead><tbody><tr><td>Stocks</td><td><code>AAPL</code>, <code>NVDA</code></td><td>Asset / company research</td></tr><tr><td>Crypto</td><td><code>BTC</code>, <code>ETH</code></td><td>Asset research and crypto analytics</td></tr><tr><td>Commodities</td><td>Gold, oil, copper</td><td>Commodity research</td></tr><tr><td>ETFs</td><td><code>SPY</code>, <code>IWM</code></td><td>ETF research</td></tr><tr><td>FX pairs</td><td><code>EUR/USD</code>, <code>USD/CHF</code></td><td>Currency Research Workspace</td></tr><tr><td>Macro indicators</td><td>Country or economic indicators</td><td>Macro research and Analytics</td></tr><tr><td>Bonds</td><td>Sovereigns and fixed income</td><td>Watchlist / Portfolio context</td></tr><tr><td>Options</td><td>Equity and crypto options</td><td>Options workspace</td></tr></tbody></table><h2 id="data-coverage-is-provider-dependent" tabindex="-1">Data coverage is provider-dependent</h2><p>Data freshness, source coverage, and availability vary by instrument and upstream provider. Zenin surfaces <strong>cached, stale, unavailable, and reference-only</strong> states where the underlying data does not support a live result.</p><p>See the <a href="/use-zenin/data-status-glossary">Data status glossary</a> for what each state means and where you will see it.</p><p><strong>Next:</strong> <a href="/get-started/create-and-access-a-workspace">Create and access a workspace</a></p>',12)])])}const m=e(o,[["render",n]]);export{u as __pageData,m as default};
